import { BooleanColumn, StringColumn, VersionColumn, Table } from '../../db'

export const sys_package = Table({
    name: 'sys_package',
    schema: {
        active: BooleanColumn({ default: true }),
        enforce_license: StringColumn({
            label: 'Subscription requirement',
            choices: {
                none: {
                    label: 'None',
                    sequence: 1,
                },
                log: {
                    label: 'Monitor',
                    sequence: 2,
                },
                enforce: {
                    label: 'Required',
                    sequence: 3,
                },
            },
            default: 'none',
        }),
        ide_created: StringColumn({ label: 'IDE Created', maxLength: 10 }),
        licensable: BooleanColumn({}),
        license_category: StringColumn({ label: 'Subscription Category' }),
        license_model: StringColumn({
            label: 'Subscription Model',
            choices: {
                none: {
                    label: 'Not applicable',
                    sequence: 1,
                },
                fulfiller: {
                    label: 'Fulfiller/Requester',
                    sequence: 2,
                },
                producer: {
                    label: 'Producer',
                    sequence: 3,
                },
                capacity: {
                    label: 'Capacity',
                    sequence: 4,
                },
                mixed: {
                    label: 'Mixed',
                    sequence: 5,
                },
                app_use: {
                    label: 'Application in use',
                    sequence: 6,
                },
            },
            default: 'none',
        }),
        name: StringColumn({ maxLength: 100 }),
        package_json: StringColumn({ label: 'Package JSON' }),
        source: StringColumn({
            label: 'ID',
            default: `javascript:_getID();

    function _getID() {
      var source = current.getValue('source');
      var sys_id = current.getValue('sys_id');
      var scope = current.getValue('scope');
      return gs.nil(scope) || scope == 'global' ? source||sys_id : source||scope;
    }`,
        }),
        // sys_class_name: systemClassNameColumn({ default: 'javascript:current.getTableName();' }),
        trackable: BooleanColumn({ default: false }),
        version: VersionColumn({}),
    },
})
